        options.put("indent", "2");
        options.put("rgbAsHex", "false");
        ConfigurationSource cfg = new ConfigurationSource(options, "testConfig");
        cssFormatter.init(options, cfg);
        assertTrue(cssFormatter.isInitialized());
    }

    @Test
